function e(t){if(!t)return"—";const n=new Date(t).getTime();if(Number.isNaN(n))return"—";const r=Math.max(1,Math.round((Date.now()-n)/1e3));return r<60?`${r} 秒前`:r<3600?`${Math.floor(r/60)} 分钟前`:r<86400?`${Math.floor(r/3600)} 小时前`:`${Math.floor(r/86400)} 天前`}function o(t){if(!t)return"--:--";const n=new Date(t);if(Number.isNaN(n.getTime()))return"--:--";const r=u=>String(u).padStart(2,"0");return`${r(n.getHours())}:${r(n.getMinutes())}:${r(n.getSeconds())}`}function f(t){if(!t||t<0)return"0 秒";if(t<60)return`${Math.round(t)} 秒`;if(t<3600)return`${Math.floor(t/60)} 分 ${Math.round(t%60)} 秒`;const n=Math.floor(t/3600),r=Math.round(t%3600/60);return`${n} 时 ${r} 分`}function i(t){if(!t)return"0 B";const n=["B","KB","MB","GB"];let r=0;for(;t>=1024&&r<n.length-1;)t/=1024,r++;return`${t.toFixed(r===0?0:1)} ${n[r]}`}function a(t){return t==null?"—":t<1e3?`${t}ms`:`${(t/1e3).toFixed(2)}s`}function $(t,n=8e3){return Math.min(100,Math.max(1.5,t/n*100))}export{o as a,a as b,e as c,i as d,f,$ as p};
